use genex::prelude::*;

/// One wall module of the kit: shell, coat and trims, turned to face the room.
fn module(frame: &mut Frame, kit: &Kit, kind: &str, at: Vec3, yaw: f32, looks: &Looks) {
    let place = Transform::from_translation(at).with_rotation(Quat::from_rotation_y(yaw));
    frame.model_with(&kit.piece(kind), place, &looks.plaster);
    frame.model_with(&kit.piece(&format!("{kind}-paint")), place, &looks.paint);
    frame.model_with(&kit.piece(&format!("{kind}-trims")), place, &looks.trim);
}

// The roles' materials: a scan at its real size for the shell, the kit's sheets for the rest.
let plaster = Material::color(Color::WHITE)
    .with_base_texture("cc0/<job>/painted_plaster_wall_diff_1k.jpg")
    .with_world_uv(2.5)
    .with_stochastic_tiling(true);
let trim = Material::color(Color::WHITE)
    .with_base_texture("kit/trim_color.webp")
    .with_normal_texture("kit/trim_normal.webp", 1.0)
    .with_orm_texture("kit/trim_orm.webp");
